func (c *CLab) Destroy(ctx context.Context, options ...DestroyOption) (err error) {
	opts := NewDestroyOptions()

	for _, opt := range options {
		opt(opts)
	}

	if c.LabRuntime != nil {
		return c.destroyWithLabRuntime(ctx, opts)
	}

	var containers []clabruntime.GenericContainer

	switch {
	case opts.all:
		containers, err = c.ListContainers(ctx)
	case c.TopoPaths.TopologyFilenameAbsPath() != "":
		containers, err = c.ListNodesContainersIgnoreNotFound(ctx)
		if err == nil {
			var tailscaleContainers []clabruntime.GenericContainer
			tailscaleContainers, err = c.discoverTailscaleContainers(ctx, opts.nodeFilter)
			containers = append(containers, tailscaleContainers...)
		}
	default:
		var listOpts []ListOption

		if c.Config.Name != "" {
			listOpts = []ListOption{WithListLabName(c.Config.Name)}
		} else {
			listOpts = []ListOption{WithListclabLabelExists()}
		}

		containers, err = c.ListContainers(ctx, listOpts...)
	}

	if err != nil {
		return err
	}

	// topo will hold the reference to the topology file
	// as the key and the respective lab directory as the referenced value
	topos := map[string]string{}

	for idx := range containers {
		topoFile, ok := containers[idx].Labels[clabconstants.TopoFile]
		if !ok {
			continue
		}

		topos[topoFile] = filepath.Dir(containers[idx].Labels[clabconstants.NodeLabDir])
	}

	// failedLabDirs records the lab directories whose destroy failed or was never
	// attempted. --cleanup keeps those directories: deleting the lab directory of
	// a lab that is still running would discard the state file destroy needs for
	// its management network cleanup on the next attempt.
	failedLabDirs := map[string]bool{}

	defer func() {
		if opts.cleanup {
			if cleanupErr := c.destroyLabDirs(topos, opts.all, failedLabDirs); cleanupErr != nil {
				err = errors.Join(err, cleanupErr)
			}
		}
	}()

	if len(topos) == 0 {
		return nil
	}

	log.Debugf("got the following topologies for destroy: %+v", topos)

	// if all, and cli doesn't have --yes flag, and in a terminal -- prompt user confirmation
	if opts.all && opts.terminalPrompt && term.IsTerminal(int(os.Stdin.Fd())) {
		err := cliPromptToDestroyAll(topos)
		if err != nil {
			return err
		}
	}

	var errs []error

	for topo, labDir := range topos {
		cc, err := c.makeCopyForDestroy(ctx, topo, labDir, *opts)
		if err != nil {
			log.Errorf("error creating clab instance for topo %q: %v", topo, err)

			errs = append(errs, fmt.Errorf(
				"error creating clab instance for topo %q: %w", topo, err))
			failedLabDirs[labDir] = true

			continue
		}

		err = cc.destroy(ctx, opts.maxWorkers, opts.keepMgmtNet)
		if err != nil {
			log.Errorf("Error occurred during the %s lab deletion: %v", cc.Config.Name, err)
			errs = append(errs, err)
			failedLabDirs[labDir] = true
		}
	}

	if len(errs) != 0 {
		return fmt.Errorf("error(s) occurred during the deletion. Check log messages")
	}

	return nil
}

// creates a mostly cloned version of the current c but set to the new topology, and with the
// necessary steps (mgmt network things) handled preparing the new CLab for destruction.
func (c *CLab) makeCopyForDestroy(
	ctx context.Context,
	topo,
	labDir string,
	opts DestroyOptions,
) (*CLab, error) {
	newOpts := []ClabOption{
		WithTimeout(c.timeout),
		// a topology edited after deploy may no longer pass the mgmt-net link checks,
		// which must not prevent the removal of the deployed lab.
		WithSkippedMgmtNetLinksCheck(),
	}

	// Try to load topology file if it exists, otherwise use lab name only.
	// This allows destroying labs even when the topology file has been deleted.
	// WithTopoPath / WithLabNameOnly must run before WithNodeFilter so filterClabNodes
	// sees topology nodes (see filterClabNodes in clab.go).
	varsFiles := opts.varsFiles
	if len(varsFiles) == 0 {
		varsFiles = c.TopoPaths.VarsFilenamesAbsPath()
	}

	if clabutils.FileOrDirExists(topo) {
		newOpts = append(newOpts, WithTopoPath(topo, varsFiles))
	} else {
		// Derive lab name from lab directory (format: clab-<labname>)
		labName := filepath.Base(labDir)
		labName = strings.TrimPrefix(labName, "clab-")
		log.Debugf("topology file %q not found, using lab name %q for destroy", topo, labName)
		newOpts = append(newOpts, WithLabNameOnly(labName))
	}

	newOpts = append(newOpts,
		WithNodeFilter(opts.nodeFilter),
		// during destroy we don't want to check bind paths
		// as it is irrelevant for this command.
		WithSkippedBindsPathsCheck(),
		WithRuntime(
			c.globalRuntimeName,
			&clabruntime.RuntimeConfig{
				Debug:            c.Config.Debug,
				Timeout:          c.timeout,
				GracefulShutdown: opts.graceful,
			},
		),
	)

	if opts.keepMgmtNet {
		newOpts = append(newOpts, WithKeepMgmtNet())
	}

	cc, err := NewContainerLab(newOpts...)
	if err != nil {
		return nil, err
	}
	if labDir != "" && clabutils.FileOrDirExists(labDir) {
		// adjust the labdir. Usually we take the PWD. but now on destroy time,
		// we might be in a different Dir.
		err = cc.TopoPaths.SetLabDir(labDir)
		if err != nil {
			return nil, err
		}
	}

	// populate the management network state (bridge names) destroy needs for the
	// removal of the iptables rules, without creating networks that are missing:
	// a lab deployed with a management network override leaves the topology's
	// default network uncreated, and creating it here would collide with the
	// subnets the override is using.
	if !cc.mgmtNetworksSkipped() {
		var bridged clabtypes.MgmtNetworks
		for _, m := range cc.allMgmtNetworks() {
			if m.Driver != clabtypes.MgmtDriverMacvlan {
				bridged = append(bridged, m)
			}
		}
		if err = cc.resolveExistingMgmtNetworks(ctx, bridged); err != nil {
			return nil, err
		}
	}

	err = cc.setMgmtNetLinkBridges()
	if err != nil {
		return nil, err
	}

	err = cc.ResolveLinks()
	if err != nil {
		return nil, err
	}

	return cc, nil
}

// resolveExistingMgmtNetworks inspects the management networks that already exist
// so their bridge names are populated, e.g. for the iptables cleanup on destroy.
// Networks that do not exist are skipped: they hold no bridge yet, and the callers
// must not create management networks. Runtimes that cannot check network existence
// keep the create-or-inspect behavior.
func (c *CLab) resolveExistingMgmtNetworks(
	ctx context.Context,
	networks clabtypes.MgmtNetworks,
) error {
	var existing clabtypes.MgmtNetworks

	for _, m := range networks {
		rt, rtErr := c.mgmtRuntime(c.globalRuntimeName, m)
		if rtErr != nil {
			// runtimes without multiple network support never created extra networks
			log.Debug(
				"Skipping management network resolution", "network", m.Network, "error", rtErr,
			)
			continue
		}

		checker, ok := rt.(clabruntime.MgmtNetworkChecker)
		if !ok {
			existing = append(existing, m)
			continue
		}

		exists, err := checker.MgmtNetworkExists(ctx)
		if err != nil {
			return err
		}
		if !exists {
			log.Debug("Skipping management network that does not exist", "network", m.Network)
			continue
		}

		existing = append(existing, m)
	}

	return c.createNetworks(ctx, existing)
}

// destroyLabDirs removes the lab directories of the destroyed labs. Directories
// recorded in failedLabDirs are kept: their labs are still running, and the
// directory holds the lab state a later destroy attempt relies on.
func (c *CLab) destroyLabDirs(
	topos map[string]string,
	all bool,
	failedLabDirs map[string]bool,
) error {
	if len(topos) == 0 {
		log.Info("no containerlab containers found")

		if !all {
			labDir := c.TopoPaths.TopologyLabDir()
			if labDir == "" {
				// Try to infer the precise lab directory when TopologyLabDir is not set,
				// e.g. destroy --name without topology file. Only look for an exact
				// clab-<name> match, never a wildcard.
				if c.Config != nil && c.Config.Name != "" {
					candidates := []string{}
					if base := os.Getenv("CLAB_LABDIR_BASE"); base != "" {
						candidates = append(candidates, filepath.Join(base, "clab-"+c.Config.Name))
					}
					if c.TopoPaths.TopologyFileIsSet() {
						candidates = append(
							candidates,
							filepath.Join(c.TopoPaths.TopologyFileDir(), "clab-"+c.Config.Name),
						)
					} else {
						if wd, err := os.Getwd(); err == nil && wd != "" {
							candidates = append(
								candidates,
								filepath.Join(wd, "clab-"+c.Config.Name),
							)
						}
					}
					for _, cand := range candidates {
						if _, err := os.Stat(cand); err == nil {
							labDir = cand
							break
						}
					}
					if labDir == "" {
						log.Info(
							"lab directory not found, nothing to clean",
							"candidates",
							candidates,
						)
						return nil
					}
				} else {
					log.Info("lab directory not found, nothing to clean")
					return nil
				}
			}

			// Safety: only remove directories that look like a lab directory.
			base := filepath.Base(labDir)
			if !strings.HasPrefix(base, "clab-") {
				log.Warnf("refusing to remove lab directory %q: unexpected name", labDir)
				return nil
			}
			if c.Config != nil && c.Config.Name != "" {
				expected := "clab-" + c.Config.Name
				if base != expected {
					log.Warnf(
						"refusing to remove lab directory %q: does not match expected %q",
						labDir,
						expected,
					)
					return nil
				}
			}

			if _, err := os.Stat(labDir); os.IsNotExist(err) {
				log.Info("lab directory not found, nothing to clean", "path", labDir)
				return nil
			} else if err != nil {
				log.Debug("failed to stat lab directory, skipping", "path", labDir, "error", err)
				return nil
			}

			log.Info("Removing lab directory", "path", labDir)
			if err := os.RemoveAll(labDir); err != nil {
				log.Errorf("error deleting lab directory: %v", err)
				return err
			}
		}

		return nil
	}

	for _, labdir := range topos {
		if failedLabDirs[labdir] {
			log.Warnf(
				"keeping lab directory %s: the lab was not destroyed, so its state is kept for a later attempt",
				labdir,
			)

			continue
		}

		err := os.RemoveAll(labdir)
		if err != nil {
			log.Errorf("error deleting lab directory: %v", err)
		}
	}

	return nil
}

func (c *CLab) destroy(ctx context.Context, maxWorkers uint, keepMgmtNet bool) error {
	var containers []clabruntime.GenericContainer
	var orphanSidecars []clabruntime.GenericContainer
	var err error

	// If we have nodes defined (from topology file), list containers by node.
	// Otherwise, list containers by lab name label (for destroy-by-name-only case).
	if len(c.Nodes) > 0 {
		containers, err = c.ListNodesContainersIgnoreNotFound(ctx)
	} else if c.Config.Name != "" {
		containers, err = c.ListContainers(ctx, WithListLabName(c.Config.Name))
	}

	if err != nil {
		return err
	}

	if len(c.Nodes) == 0 {
		c.addMgmtNetworksFromContainers(containers)
	}

	if len(c.Nodes) > 0 {
		tailscaleContainers, err := c.discoverTailscaleContainers(ctx, c.nodeFilter)
		if err != nil {
			return err
		}
		for _, ctr := range tailscaleContainers {
			if _, desired := c.Nodes[ctr.Labels[clabconstants.NodeName]]; desired {
				continue
			}
			containers = append(containers, ctr)
			if ctr.Labels[clabconstants.ToolType] == "" {
				orphanSidecars = append(orphanSidecars, ctr)
			}
		}
	}

	if len(containers) == 0 {
		if len(c.Nodes) > 0 && len(c.Links) > 0 {
			c.deleteSpecialLinkNodes(ctx)
		}
		return nil
	}

	if maxWorkers == 0 {
		maxWorkers = uint(len(containers))
	}

	log.Info("Destroying lab", "name", c.Config.Name)

	// If we have nodes defined, use the normal node-based deletion.
	// Otherwise, delete containers directly via the runtime (for destroy-by-name-only case).
	if len(c.Nodes) > 0 {
		c.preDestroyNodes(ctx, slices.Collect(maps.Values(c.Nodes)), maxWorkers)

		err := clablinks.CleanupFilteredLinks(
			ctx,
			c.Config.Topology.Links,
			c.Config.Name,
			c.nodeFilter,
		)
		if err != nil {
			return err
		}
		c.deleteNodes(ctx, maxWorkers)
		c.deleteContainersDirect(ctx, orphanSidecars)
	} else {
		c.deleteContainersDirect(ctx, containers)
	}

	c.deleteToolContainers(ctx)

	log.Info("Removing host entries", "path", "/etc/hosts")

	err = c.DeleteEntriesFromHostsFile()
	if err != nil {
		return fmt.Errorf("error while trying to clean up the hosts file: %w", err)
	}

	log.Info("Removing SSH config", "path", c.TopoPaths.SSHConfigPath())

	err = c.RemoveSSHConfig(c.TopoPaths)
	if err != nil {
		log.Errorf("failed to remove ssh config file: %v", err)
	}

	// delete container network namespaces symlinks
	for _, node := range c.Nodes {
		err = node.DeleteNetnsSymlink()
		if err != nil {
			return fmt.Errorf("error while deleting netns symlinks: %w", err)
		}
	}

	// delete every defined management network, including extra networks
	// that apply may have left without nodes, and networks a previous
	// deployment recorded in the lab state but the topology no longer defines
	for _, m := range c.mgmtNetworksForCleanup() {
		if m.Network == "bridge" || keepMgmtNet {
			continue
		}
		log.Debugf("Calling DeleteNet method. Management network value is: %+v", m)

		rt, rtErr := c.mgmtRuntime(c.globalRuntimeName, m)
		if rtErr != nil {
			// runtimes without multiple network support never created extra networks
			log.Debug("Skipping management network deletion", "network", m.Network, "error", rtErr)
			continue
		}
		if err = rt.DeleteNet(ctx); err != nil {
			switch {
			case err.Error() == fmt.Sprintf("Error: No such network: %s", m.Network):
			case strings.Contains(err.Error(), fmt.Sprintf(" network %s not found", m.Network)):
			default:
				log.Error(err)
			}
		}
	}

	return nil
}

func (c *CLab) addMgmtNetworksFromContainers(containers []clabruntime.GenericContainer) {
	for _, ctr := range containers {
		switch name := ctr.NetworkName; name {
		case "", "unknown", "bridge", "host", "none":
		default:
			if c.mgmtNetByNetwork(name).Network == name {
				continue
			}
			c.Config.MgmtNetworks = append(c.Config.MgmtNetworks, &clabtypes.MgmtNet{
				Network:        name,
				Bridge:         ctr.Labels[clabconstants.NodeMgmtNetBr],
				ExternalAccess: new(true),
			})
		}
	}
}

// mgmtNetworksForCleanup returns the management networks to delete on destroy:
// the topology-defined ones plus any network a previous deployment recorded in
// the lab state but that the current topology no longer defines. Without the
// state record a network dropped from the mgmt list would never be removed.
func (c *CLab) mgmtNetworksForCleanup() clabtypes.MgmtNetworks {
	networks := c.allMgmtNetworks()

	state, err := c.LoadState()
	if err != nil {
		log.Warn("Unable to load the management networks recorded in the lab state", "error", err)
		return networks
	}
	if state == nil {
		return networks
	}

	defined := make(map[string]bool, len(networks))
	for _, m := range networks {
		defined[m.Network] = true
	}
	for _, name := range state.MgmtNetworks {
		if defined[name] {
			continue
		}
		defined[name] = true
		// ExternalAccess mirrors the default every management network gets, so
		// the forwarding rule installed for the network is cleaned up too.
		networks = append(networks, &clabtypes.MgmtNet{
			Network:        name,
			ExternalAccess: new(true),
		})
	}

	return networks
}

func (c *CLab) deleteApplyNodes(ctx context.Context, plan *applyPlan) error {
	nodeNames := make([]string, 0, len(plan.deletedNodeSet)+len(plan.recreatedNodeSet))
	for nodeName := range plan.deletedNodeSet {
		nodeNames = append(nodeNames, nodeName)
	}
	for nodeName := range plan.recreatedNodeSet {
		nodeNames = append(nodeNames, nodeName)
	}
	sort.Strings(nodeNames)

	hookNodes := make([]clabnodes.Node, 0, len(nodeNames))
	var tailscaleContainers []clabruntime.GenericContainer
	for _, nodeName := range nodeNames {
		runtimeNode := plan.currentNodes[nodeName]
		if runtimeNode == nil {
			return fmt.Errorf("runtime node %q not found", nodeName)
		}
		if runtimeNode.external || runtimeNode.rootNamespaceBased {
			continue
		}
		if len(runtimeNode.containers) > 0 &&
			runtimeNode.containers[0].Labels[clabconstants.NodeKind] == clabnodestailscale.KindName {
			tailscaleContainers = append(tailscaleContainers, runtimeNode.containers...)
			continue
		}
		if node, ok := c.Nodes[nodeName]; ok {
			hookNodes = append(hookNodes, node)
		}
	}
	var logoutWg sync.WaitGroup
	for _, ctr := range tailscaleContainers {
		logoutWg.Go(func() { c.logoutTailscaleContainer(ctx, ctr) })
	}
	c.preDestroyNodes(ctx, hookNodes, 0)
	logoutWg.Wait()

	for _, nodeName := range nodeNames {
		runtimeNode := plan.currentNodes[nodeName]
		if runtimeNode.external || runtimeNode.rootNamespaceBased {
			continue
		}

		for i := len(runtimeNode.containers) - 1; i >= 0; i-- {
			ctr := runtimeNode.containers[i]
			if len(ctr.Names) == 0 {
				return fmt.Errorf("runtime container for node %q has no name", nodeName)
			}

			runtime := ctr.Runtime
			if runtime == nil {
				runtime = c.globalRuntime()
			}

			action := "Deleting node"
			if _, recreate := plan.recreatedNodeSet[nodeName]; recreate {
				action = "Deleting node for recreate"
			}
			log.Info(action, "node", nodeName, "container", ctr.Names[0])
			if err := runtime.DeleteContainer(ctx, ctr.Names[0]); err != nil {
				return fmt.Errorf("failed deleting node %q: %w", nodeName, err)
			}

			_ = clabutils.DeleteNetnsSymlink(ctr.Names[0])
		}
	}

	return nil
}

// preDestroyNodes runs the PreDestroy stage of the given nodes concurrently, before any of them
// is deleted. Nodes without a container are skipped. A workers value of 0 runs all hooks at once.
func (*CLab) preDestroyNodes(ctx context.Context, nodes []clabnodes.Node, workers uint) {
	if workers == 0 || workers > uint(len(nodes)) {
		workers = uint(len(nodes))
	}

	sem := make(chan struct{}, workers)
	wg := new(sync.WaitGroup)

	for _, n := range nodes {
		wg.Add(1)
		sem <- struct{}{}

		go func() {
			defer wg.Done()
			defer func() { <-sem }()

			if n.GetContainerStatus(ctx) == clabruntime.NotFound {
				return
			}

			if err := n.PreDestroy(ctx); err != nil {
				log.Warnf("node %q pre-destroy hook failed: %v", n.Config().ShortName, err)
			}
		}()
	}

	wg.Wait()
}

func (c *CLab) deleteNodes(ctx context.Context, workers uint) {
	wg := new(sync.WaitGroup)

	concurrentChan := make(chan clabnodes.Node)

	workerFunc := func(i uint, input chan clabnodes.Node, wg *sync.WaitGroup) {
		defer wg.Done()

		for {
			select {
			case n := <-input:
				if n == nil {
					log.Debugf("Worker %d terminating...", i)
					return
				}

				err := n.Delete(ctx)
				if err != nil {
					log.Errorf("could not remove container %q: %v", n.Config().LongName, err)
				}
			case <-ctx.Done():
				return
			}
		}
	}

	// start concurrent workers
	wg.Add(int(workers))

	for i := range workers {
		go workerFunc(i, concurrentChan, wg)
	}

	// send nodes to workers
	for _, n := range c.Nodes {
		concurrentChan <- n
	}

	// close channel to terminate the workers
	close(concurrentChan)

	wg.Wait()

	// Host and mgmt-br links must be removed only after node workers finish.
	// vxlan-stitch teardown deletes veth pairs from containers concurrently with
	// host-namespace VXLAN interfaces; running both at once races netlink deletes.
	c.deleteSpecialLinkNodes(ctx)
}

func (c *CLab) deleteSpecialLinkNodes(ctx context.Context) {
	specialNodes := append(
		[]clablinks.Node{clablinks.GetHostLinkNode()},
		clablinks.GetMgmtBrLinkNodes()...,
	)
	for _, n := range specialNodes {
		err := n.Delete(ctx)
		if err != nil {
			log.Warn(err)
		}
	}
}

// deleteContainersDirect deletes containers directly via the runtime API.
// This is used when we don't have node objects (e.g., destroy-by-name-only case).
func (c *CLab) deleteContainersDirect(
	ctx context.Context,
	containers []clabruntime.GenericContainer,
) {
	for _, cont := range containers {
		if len(cont.Names) == 0 {
			log.Warnf("skipping container %s with no names", cont.ID)
			continue
		}
		name := cont.Names[0]
		log.Infof("Removing container: %s", name)

		c.logoutTailscaleContainer(ctx, cont)
		rt := cont.Runtime
		if rt == nil {
			rt = c.globalRuntime()
		}
		err := rt.DeleteContainer(ctx, name)
		if err != nil {
			log.Errorf("could not remove container %q: %v", name, err)
		}
	}
}

func (c *CLab) deleteToolContainers(ctx context.Context) {
	toolTypes := []string{"sshx", "gotty"}

	if len(c.nodeFilter) == 0 {
		toolTypes = append(toolTypes, clabnodestailscale.ToolType)
	}

	for _, toolType := range toolTypes {
		toolFilter := []*clabtypes.GenericFilter{
			{
				FilterType: "label",
				Field:      clabconstants.ToolType,
				Operator:   "=",
				Match:      toolType,
			},
			{
				FilterType: "label",
				Field:      clabconstants.Containerlab,
				Operator:   "=",
				Match:      c.Config.Name,
			},
		}

		containers, err := c.globalRuntime().ListContainers(ctx, toolFilter)
		if err != nil {
			log.Error("Failed to list tool containers", "tool", toolType, "error", err)
			continue
		}

		if len(containers) == 0 {
			log.Debug("No tool containers found for lab", "tool", toolType, "lab", c.Config.Name)
			continue
		}

		log.Info("Found tool containers associated with a lab", "tool", toolType, "lab",
			c.Config.Name, "count", len(containers))

		for idx := range containers {
			containerName := strings.TrimPrefix(containers[idx].Names[0], "/")

			log.Info("Removing tool container", "tool", toolType, "container", containerName)

			c.logoutTailscaleContainer(ctx, containers[idx])
			if err := c.globalRuntime().DeleteContainer(ctx, containerName); err != nil {
				log.Error("Failed to remove tool container", "tool", toolType,
					"container", containerName, "error", err)
			} else {
				log.Info(
					"Tool container removed successfully",
					"tool",
					toolType,
					"container",
					containerName,
				)
			}
		}
	}
}

