func (lr *LinkVxlanRaw) resolveStitchedVEthComponent(
	params *ResolveParams,
) (Link, Endpoint, error) {
	var err error

	// hostIface is the name of the host interface that will be created
	hostIface := clabutils.SanitizeInterfaceName(
		fmt.Sprintf("ve-%s_%s", lr.Endpoint.Node, lr.Endpoint.Iface),
	)

	// when tools vxlan create command is used, the hostIface is provided
	// by the user, otherwise it is generated
	if params.VxlanIfaceNameOverwrite != "" {
		hostIface = clabutils.SanitizeInterfaceName(params.VxlanIfaceNameOverwrite)
	}

	lhr := &LinkHostRaw{
		LinkCommonParams: lr.LinkCommonParams,
		HostInterface:    hostIface,
		Endpoint: &EndpointRaw{
			Node:  lr.Endpoint.Node,
			Iface: lr.Endpoint.Iface,
		},
	}

	hl, err := lhr.Resolve(params)
	if err != nil {
		return nil, nil, err
	}

	if hl == nil {
		return nil, nil, fmt.Errorf("failed to resolve host veth component for vxlan-stitch")
	}

	eps := hl.GetEndpoints()
	if len(eps) != 2 {
		return nil, nil, fmt.Errorf(
			"expected host veth component to resolve to 2 endpoints, got %d",
			len(eps),
		)
	}

	stitchEp, ok := endpointByInterfaceName(eps, hostIface)
	if !ok {
		return nil, nil, fmt.Errorf(
			"expected host veth component to include endpoint %q",
			hostIface,
		)
	}

	return hl, stitchEp, nil
}

func endpointByInterfaceName(endpoints []Endpoint, ifaceName string) (Endpoint, bool) {
	for _, ep := range endpoints {
		if ep != nil && ep.GetIfaceName() == ifaceName {
			return ep, true
		}
	}
	return nil, false
}

// resolveStitchedVxlan resolves the stitched raw vxlan link.
func (lr *LinkVxlanRaw) resolveStitchedVxlan(params *ResolveParams) (*VxlanStitched, error) {
	// prepare the vxlan struct
	vxlanLink, err := lr.resolveVxlan(params, true)
	if err != nil {
		return nil, err
	}

	// prepare the veth struct
	vethLink, stitchEp, err := lr.resolveStitchedVEthComponent(params)
	if err != nil {
		return nil, err
	}

	// return the stitched vxlan link
	vxlanStitchedLink := NewVxlanStitched(vxlanLink, vethLink, stitchEp)

	return vxlanStitchedLink, nil
}

